import * as cdk from "@aws-cdk/core";

import * as s3 from "@aws-cdk/aws-s3";
import * as s3Deploy from "@aws-cdk/aws-s3-deployment";

interface Props {
  websiteIndexDocument: string;
  buildFolder: string;
  websiteErrorDocument?: string;
  bucketProps?: Omit<s3.BucketProps, keyof Props>;
  deploymentProps?: Omit<
    s3Deploy.BucketDeploymentProps,
    "sources" | "destinationBucket"
  >;
  uniqueId: string;
}

export class S3HostBuildFolderNestedStack extends cdk.NestedStack {
  bucket: s3.Bucket;
  deployment: s3Deploy.BucketDeployment;
  constructor(
    scope: cdk.Construct,
    id: string,
    props: Props & cdk.NestedStackProps,
  ) {
    super(scope, id, props);

    this.bucket = new s3.Bucket(this, `${props.uniqueId}HostingBucket`, {
      publicReadAccess: true,
      ...props.bucketProps,
      websiteIndexDocument: props.websiteIndexDocument,
      websiteErrorDocument: props.websiteErrorDocument,
    });

    this.deployment = new s3Deploy.BucketDeployment(
      this,
      `${props.uniqueId}BucketDeployment`,
      {
        ...props.deploymentProps,
        destinationBucket: this.bucket,
        sources: [s3Deploy.Source.asset(props.buildFolder)],
      },
    );

    new cdk.CfnOutput(this, `${props.uniqueId}BucketWebsiteURL`, {
      value: this.bucket.bucketWebsiteUrl,
      description: "The public URL of the hosted website",
      exportName: `${props.uniqueId}BucketWebsiteUrl`,
    });
  }
}

export class S3HostBuildFolderRootStack extends cdk.Stack {
  bucket: s3.Bucket;
  deployment: s3Deploy.BucketDeployment;
  constructor(scope: cdk.Construct, id: string, props: Props & cdk.StackProps) {
    super(scope, id, props);
    const stack = new S3HostBuildFolderNestedStack(
      this,
      `${props.uniqueId}S3HostBuildFolderStack`,
      props,
    );

    this.bucket = stack.bucket;
    this.deployment = stack.deployment;
  }
}

import * as cognito from "@aws-cdk/aws-cognito";
import * as iam from "@aws-cdk/aws-iam";
import * as cdk from "@aws-cdk/core";

interface Props extends cdk.NestedStackProps {
  uniqueId: string;
  userPoolProps?: cognito.UserPoolProps;
  allowUnauthenticatedIdentities: boolean;
  identityPoolProps?: Omit<
    cognito.CfnIdentityPoolProps,
    "allowUnauthenticatedIdentities" | "cognitoIdentityProviders"
  >;
  userPoolClientProps?: cognito.UserPoolClientProps;
}

export class SimpleCognitoNestedStack extends cdk.NestedStack {
  userPool: cognito.UserPool;
  identityPool: cognito.CfnIdentityPool;
  appClient: cognito.UserPoolClient;
  authenticatedRole: iam.Role;
  unauthenticatedRole: iam.Role;
  constructor(scope: cdk.Construct, id: string, props: Props) {
    super(scope, id, props);

    this.userPool = new cognito.UserPool(
      this,
      `UserPool${props.uniqueId}`,
      props.userPoolProps,
    );

    this.appClient = this.userPool.addClient(
      `AppClient${props.uniqueId}`,
      props.userPoolClientProps,
    );

    this.identityPool = new cognito.CfnIdentityPool(
      this,
      `IdentityProvider${props.uniqueId}`,
      {
        ...props.identityPoolProps,
        allowUnauthenticatedIdentities: props.allowUnauthenticatedIdentities,
        cognitoIdentityProviders: [
          {
            clientId: this.appClient.userPoolClientId,
            providerName: this.userPool.userPoolProviderName,
          },
        ],
      },
    );

    this.authenticatedRole = new iam.Role(
      this,
      `CognitoDefaultAuthenticatedRole${props.uniqueId}`,
      {
        assumedBy: new iam.FederatedPrincipal(
          "cognito-identity.amazonaws.com",
          {
            StringEquals: {
              "cognito-identity.amazonaws.com:aud": this.identityPool.ref,
            },
            "ForAnyValue:StringLike": {
              "cognito-identity.amazonaws.com:amr": "authenticated",
            },
          },
          "sts:AssumeRoleWithWebIdentity",
        ),
      },
    );
    this.authenticatedRole.addToPolicy(
      new iam.PolicyStatement({
        actions: ["cognito-sync:*", "cognito-identity:*"],
        resources: ["*"],
      }),
    );

    this.unauthenticatedRole = new iam.Role(
      this,
      `CognitoDefaultUnauthenticatedRole${props.uniqueId}`,
      {
        assumedBy: new iam.FederatedPrincipal(
          "cognito-identity.amazonaws.com",
          {
            StringEquals: {
              "cognito-identity.amazonaws.com:aud": this.identityPool.ref,
            },
            "ForAnyValue:StringLike": {
              "cognito-identity.amazonaws.com:amr": "unauthenticated",
            },
          },
          "sts:AssumeRoleWithWebIdentity",
        ),
      },
    );
    this.unauthenticatedRole.addToPolicy(
      new iam.PolicyStatement({
        actions: ["cognito-sync:*"],
        resources: ["*"],
      }),
    );

    new cognito.CfnIdentityPoolRoleAttachment(
      this,
      `DefaultValidRole${props.uniqueId}`,
      {
        identityPoolId: this.identityPool.ref,
        roles: {
          unauthenticated: this.unauthenticatedRole.roleArn,
          authenticated: this.authenticatedRole.roleArn,
        },
      },
    );
  }
}

export class SimpleCognitoRootStack extends cdk.Stack {
  userPool: cognito.UserPool;
  identityPool: cognito.CfnIdentityPool;
  appClient: cognito.UserPoolClient;
  authenticatedRole: iam.Role;
  unauthenticatedRole: iam.Role;
  constructor(scope: cdk.Construct, id: string, props: Props & cdk.StackProps) {
    super(scope, id, props);
    const stack = new SimpleCognitoNestedStack(
      this,
      `${props.uniqueId}SimpleCognitoStack`,
      props,
    );

    this.userPool = stack.userPool;
    this.identityPool = stack.identityPool;
    this.appClient = stack.appClient;
    this.authenticatedRole = stack.authenticatedRole;
    this.unauthenticatedRole = stack.unauthenticatedRole;
  }
}

import * as cdk from "@aws-cdk/core";
import * as lambda from "@aws-cdk/aws-lambda";
import * as events from "@aws-cdk/aws-events";
import * as targets from "@aws-cdk/aws-events-targets";

interface Props {
  uniqueId: string;
  cronOptions: events.CronOptions;
  lambdaOptions: lambda.FunctionProps;
  ruleOptions?: Omit<events.RuleProps, "schedule">;
}

export class CronLambdaNestedStack extends cdk.NestedStack {
  rule: events.Rule;
  function: lambda.Function;
  constructor(
    scope: cdk.Construct,
    id: string,
    props: Props & cdk.NestedStackProps,
  ) {
    super(scope, id, props);

    this.rule = new events.Rule(this, "ScheduleRule" + props.uniqueId, {
      ...props.ruleOptions,
      schedule: events.Schedule.cron(props.cronOptions),
    });

    this.function = new lambda.Function(
      this,
      `LambdaFunction` + props.uniqueId,
      props.lambdaOptions,
    );

    this.rule.addTarget(new targets.LambdaFunction(this.function));
  }
}

export class CronLambdaRootStack extends cdk.Stack {
  rule: events.Rule;
  function: lambda.Function;
  constructor(scope: cdk.Construct, id: string, props: Props & cdk.StackProps) {
    super(scope, id, props);
    const stack = new CronLambdaNestedStack(
      this,
      `${props.uniqueId}CronLambdaNestedStack`,
      props,
    );

    this.rule = stack.rule;
    this.function = stack.function;
  }
}

